INSERT INTO public.notices (school_id, title, slug, category, date, description, content, is_pinned, is_published, image_url) VALUES
('a1000000-0000-0000-0000-000000000001', 'Admissions Open for Academic Session 2025–26 (Pre-School to Class XI)', 'admissions-open-2025-26', 'Admissions', '2025-06-15', 'Registrations are open for Pre-School (Nursery), Pre-Primary (KG), and Classes I to XI. Limited seats available in Science & Commerce streams.', 'Online registration and prospectus are available at the school reception and official portal. Parents can visit the school office on all working days between 8:30 AM and 2:00 PM.', TRUE, TRUE, 'https://images.unsplash.com/photo-1580582932707-520aed937b7b?w=800&q=80'),
('a1000000-0000-0000-0000-000000000001', 'Annual Term-End Examination Schedule & Date Sheet Released', 'term-end-exam-datesheet-2025', 'Examination', '2025-06-08', 'Comprehensive date sheet for Classes I through XII has been published on the school portal. Practical exams commence shortly.', 'Students are requested to bring standard school stationery and valid identity cards. The detailed subject-wise timetable is attached.', FALSE, TRUE, 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=800&q=80'),
('a1000000-0000-0000-0000-000000000001', 'Summer Vacation Circular & Holiday Homework Guidelines', 'summer-vacation-circular-2025', 'Holiday', '2025-05-28', 'The school will observe summer vacation. Holiday homework booklets are uploaded in the Downloads section.', 'School office will remain open for administrative and admission queries between 9:00 AM and 1:00 PM throughout the break.', FALSE, TRUE, 'https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=800&q=80'),
('a1000000-0000-0000-0000-000000000001', 'Phenomenal Class X & XII CBSE Board Examination Results 2024–25', 'board-examination-results-2025', 'Achievement', '2025-05-20', 'Decent Public School records a 100% pass rate with over 45 students scoring above 90% aggregate in CBSE Boards.', 'Heartiest congratulations to our meritorious students, dedicated faculty members, and proud parents for this spectacular achievement.', TRUE, TRUE, 'https://images.unsplash.com/photo-1523050854058-8df90110c9f1?w=800&q=80'),
('a1000000-0000-0000-0000-000000000001', 'Inter-School Robotics & AI Science Fest Registration', 'robotics-ai-fest-2025', 'Event', '2025-05-15', 'Students of Classes VI–XII are invited to participate in the upcoming North Delhi Inter-School Robotics & AI Fest.', 'Events include Robo-Race, STEM Project Display, Coding Hackathon, and Drone Obstacle Course. Register through Class Teachers.', FALSE, TRUE, 'https://images.unsplash.com/photo-1461896836934-ffe607ba8211?w=800&q=80'),
('a1000000-0000-0000-0000-000000000001', 'Revised School Uniform & ID Card Distribution Schedule', 'uniform-id-distribution-2025', 'Circular', '2025-05-10', 'Parents can collect the new session identity cards and customized house badges from the administrative wing.', 'Please adhere to the allotted class-wise timing slots to ensure smooth distribution and avoid overcrowding.', FALSE, TRUE, 'https://images.unsplash.com/photo-1509062522246-3755977927d7?w=800&q=80');
INSERT INTO public.events (school_id, title, slug, description, event_date, end_date, time, venue, category, status, cover_image_url, is_published) VALUES
('a1000000-0000-0000-0000-000000000001', 'Annual Sports Extravaganza – "Tarang"', 'annual-sports-day-2025', 'Track and field athletics, 100m sprint, relay, March Past, and inter-house championship tournament.', '2025-10-15', '2025-10-16', '08:00 AM – 02:00 PM', 'Decent Public School Sports Ground', 'Sports', 'upcoming', 'https://images.unsplash.com/photo-1461896836934-ffe607ba8211?w=800&q=80', TRUE),
('a1000000-0000-0000-0000-000000000001', '79th Independence Day Cultural Celebration', 'independence-day-2025', 'Patriotic song recitals, flag hoisting ceremony, drama on freedom struggle, and band display.', '2025-08-15', NULL, '08:30 AM – 11:30 AM', 'School Main Auditorium & Quadrangle', 'Celebration', 'upcoming', 'https://images.unsplash.com/photo-1531482615713-2afd69097998?w=800&q=80', TRUE),
('a1000000-0000-0000-0000-000000000001', 'Annual Science, Tech & Math Exhibition – "Avishkar"', 'science-tech-exhibition-2025', 'Live model demonstrations, working robotics projects, eco-sustainability zone, and interactive math games.', '2025-08-22', '2025-08-23', '09:00 AM – 01:30 PM', 'Senior School Multi-Purpose Hall', 'Academic', 'upcoming', 'https://images.unsplash.com/photo-1532094349884-543559621b5a?w=800&q=80', TRUE),
('a1000000-0000-0000-0000-000000000001', 'Inter-House Cultural Dance & Music Fest – "Jhankar"', 'cultural-dance-music-fest-2025', 'Classical and contemporary group dances, solo instrumental performances, and choir competitions.', '2025-09-12', '2025-09-13', '09:30 AM – 02:00 PM', 'School Auditorium', 'Cultural', 'upcoming', 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=800&q=80', TRUE),
('a1000000-0000-0000-0000-000000000001', 'Annual Prize Distribution & Scholar Badge Ceremony', 'annual-prize-distribution-2025', 'Honouring academic toppers, sports stars, and all-rounders of the 2024–25 session.', '2025-03-20', NULL, '10:00 AM – 01:00 PM', 'School Auditorium', 'Academic', 'past', 'https://images.unsplash.com/photo-1523050854058-8df90110c9f1?w=800&q=80', TRUE),
('a1000000-0000-0000-0000-000000000001', 'Republic Day Parade & Patriotic Tableau Display', 'republic-day-2025', 'Grand parade, NCC cadet march, gymnastics display, and patriotic dance renditions.', '2025-01-26', NULL, '08:30 AM – 11:30 AM', 'School Sports Complex', 'Celebration', 'past', 'https://images.unsplash.com/photo-1551632811-561732d1e306?w=800&q=80', TRUE);
INSERT INTO public.faculty (school_id, name, designation, department, subject, qualification, experience_years, photo_url, bio, message, sort_order, is_published) VALUES
('a1000000-0000-0000-0000-000000000001', 'Dr. Ananya Sharma', 'Principal', 'Administration', 'Educational Leadership & Administration', 'M.Ed., Ph.D. (Education), UGC-NET', '22+ Years', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=500&q=80', 'Leading Decent Public School with a student-centric vision focused on values, critical inquiry, and academic brilliance.', 'At Decent Public School, we nurture every child into a visionary thinker, compassionate human being, and resilient leader.', 1, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Mr. Vikram Nair', 'Vice Principal & PGT Physics', 'Science', 'Physics', 'M.Sc. (Physics), B.Ed., CTET', '20 Years', 'https://images.unsplash.com/photo-1560250097-0b93528c311a?w=500&q=80', 'Expert mentor in higher secondary physics with deep experience in CBSE evaluation and competitive entrance foundations.', 'Curiosity and scientific temperament form the cornerstone of experiential learning.', 2, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Mrs. Pooja Iyer', 'Head of Department – Science', 'Science', 'Chemistry', 'M.Sc. (Organic Chemistry), B.Ed.', '16 Years', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?w=500&q=80', 'Dedicated chemistry educator passionate about hands-on lab experiments and innovative audio-visual pedagogy.', 'Chemistry is all around us. Making concepts tangible is our everyday mission.', 3, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Mr. Arjun Reddy', 'Head of Department – Mathematics', 'Mathematics', 'Mathematics & Applied Statistics', 'M.Sc. (Mathematics), B.Ed.', '18 Years', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=500&q=80', 'Specialist in simplifying abstract mathematics through logical visualization and practical problem-solving methods.', 'Mathematics teaches us that every problem has a structured solution if broken down step-by-step.', 4, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Ms. Riya Chandra', 'Senior PGT – English & Debating Coach', 'Languages', 'English Literature', 'M.A. (English), B.Ed., Cambridge CELTA', '14 Years', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=500&q=80', 'Oratory mentor and editor of the school magazine. Fosters expressive vocabulary, literature appreciation, and debating eloquence.', 'Words have the power to change minds and inspire hearts.', 5, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Mr. Deepak Singh', 'Head of Physical Education & Sports', 'Sports', 'Physical Education & Athletics', 'M.P.Ed., NIS Certified Coach', '10 Years', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=500&q=80', 'National level sports enthusiast training students in football, basketball, athletics, and self-defense.', 'Physical fitness builds discipline, teamwork, and an unbeatable mental fortitude.', 6, TRUE);
INSERT INTO public.facilities (school_id, title, icon, image_url, description, features, sort_order, is_published) VALUES
('a1000000-0000-0000-0000-000000000001', 'Smart Digital Classrooms', 'monitor', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=800&q=80', 'Interactive smart boards, projectors, high-speed Wi-Fi, and 3D digital curriculum modules in every classroom.', '["Interactive Touch Panels", "Multimedia Audio Systems", "Ergonomic Modular Furniture", "Air-Conditioned Comfort", "Connected Cloud Teaching"]'::jsonb, 1, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Advanced Science Laboratories', 'flask', 'https://images.unsplash.com/photo-1532094349884-543559621b5a?w=800&q=80', 'Dedicated Physics, Chemistry, and Biology laboratories equipped with modern apparatus, digital microscopes, and safety showers.', '["Separate Physics, Chemistry & Biology Labs", "Precision Digital Equipment", "Comprehensive Safety Stations", "Qualified Lab Attendants", "Hands-on Practical Sessions"]'::jsonb, 2, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Next-Gen Computer & AI Lab', 'computer', 'https://images.unsplash.com/photo-1543269865-cbf427effbad?w=800&q=80', 'High-performance computers, high-speed fiber broadband, Python & Scratch programming suites, and robotics toolkits.', '["Dual Core & Core i7 Systems", "Gigabit Fiber Internet", "Python, C++ & Web Tools", "Robotics & IoT Workbenches", "Dedicated UPS Backup"]'::jsonb, 3, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Central Knowledge & Resource Library', 'book', 'https://images.unsplash.com/photo-1509062522246-3755977927d7?w=800&q=80', 'A peaceful sanctuary housing over 15,000 books, national periodicals, digital journals, encyclopedias, and an e-reader section.', '["15,000+ Curated Books", "Quiet Reading Zones", "Periodicals & Reference Section", "E-Library Terminals", "Kindle & Audio-Book Access"]'::jsonb, 4, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Multi-Sport Complex & Grounds', 'dribbble', 'https://images.unsplash.com/photo-1461896836934-ffe607ba8211?w=800&q=80', 'Full-sized football pitch, synthetic basketball court, indoor badminton courts, cricket nets, and 200m athletics track.', '["Synthetic Basketball Court", "Football Pitch", "Cricket Net Practice", "Indoor Badminton & Table Tennis", "Trained Sports Coaches"]'::jsonb, 5, TRUE),
('a1000000-0000-0000-0000-000000000001', 'GPS-Tracked Safe School Fleet', 'bus', 'https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?w=800&q=80', 'Air-conditioned buses covering all major sectors of Rohini, Pitampura, Shalimar Bagh, Paschim Vihar, and adjoining regions.', '["Real-Time GPS Tracking", "On-Board CCTV Cameras", "Female Attendants on Board", "First-Aid & Speed Governors", "Parent App Notifications"]'::jsonb, 6, TRUE),
('a1000000-0000-0000-0000-000000000001', '24/7 Safety & Campus Surveillance', 'shield', 'https://images.unsplash.com/photo-1557597774-9d273605dfa9?w=800&q=80', 'Comprehensive security framework including biometric gates, 120+ CCTV cameras, trained security guards, and fire safety systems.', '["120+ High-Def CCTV Cameras", "Biometric Visitor Management", "Trained Security Personnel", "Fire-Fighting Hydrant System", "Doctor on Campus / Medical Infirmary"]'::jsonb, 7, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Performing Arts, Music & Dance Studio', 'palette', 'https://images.unsplash.com/photo-1560785496-3c9d27877182?w=800&q=80', 'Spacious artistic studio with acoustic paneling, musical instruments (keyboard, tabla, guitar, drums), and dance mirrors.', '["Acoustic Soundproof Studio", "Classical & Western Instruments", "Mirrored Dance Practice Area", "Fine Arts & Pottery Zone", "Audio Recording Setup"]'::jsonb, 8, TRUE);
INSERT INTO public.achievements (school_id, title, description, category, year, icon, is_highlight, sort_order, is_published) VALUES
('a1000000-0000-0000-0000-000000000001', 'CBSE Board Academic Excellence Award 2024–25', 'Awarded for achieving 100% pass results with 45+ students scoring 90% and above in Class X and XII examinations.', 'academic', '2024–25', 'award', TRUE, 1, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Top Ranker – National Science Olympiad (NSO)', 'Class X student Master Aarav Gupta bagged All India Rank 14 with a Gold Medal of Excellence.', 'academic', '2024–25', 'star', FALSE, 2, TRUE),
('a1000000-0000-0000-0000-000000000001', 'North Delhi District Inter-School Football Championship', 'Decent Public School senior boys football team emerged champions, scoring 16 goals across the knockout tournament.', 'sports', '2024–25', 'trophy', TRUE, 3, TRUE),
('a1000000-0000-0000-0000-000000000001', 'State Athletics Gold & Silver Medals (100m & 4x100m Relay)', 'Our senior sprint team clinched Gold in the 4x100m relay and Silver in the 200m individual sprint at Delhi State Meet.', 'sports', '2024–25', 'medal', FALSE, 4, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Best Drama Performance – Delhi Inter-School Theatre Festival', 'The senior drama troupe won Best Play for their original Hindi social drama "Udaan", receiving a standing ovation.', 'cultural', '2024–25', 'star', TRUE, 5, TRUE),
('a1000000-0000-0000-0000-000000000001', 'National Youth Art & Creative Painting Award', 'Class IX student Ms. Sneha Roy won 1st position in the All India Wildlife Conservation Painting Contest.', 'cultural', '2024–25', 'award', FALSE, 6, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Best Green Campus & Eco-Initiative School of the Year', 'Recognised by Delhi Education Forum for zero single-use plastic policy, solar roof panels, and rainwater harvesting.', 'awards', '2024', 'award', TRUE, 7, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Education Excellence Award for Holistic Development', 'Conferred with the Best Co-Educational School in North-West Delhi by National School Ratings Council.', 'awards', '2023–24', 'award', FALSE, 8, TRUE);
