INSERT INTO public.faqs (school_id, question, answer, category, keywords, sort_order, is_published) VALUES
('a1000000-0000-0000-0000-000000000001', 'What is the admission procedure for the session 2025–26?', 'Admissions for Pre-School (Nursery) to Class XI open each year in line with Directorate of Education guidelines. Parents can register online via the Admissions page or collect the registration form from the school counter. An interaction/written assessment is conducted for Classes I and above.', 'Admissions', ARRAY['admission', 'admission procedure', 'apply', 'form', 'registration', 'nursery admission', 'entry', 'process'], 1, TRUE),
('a1000000-0000-0000-0000-000000000001', 'What are the school and office timings?', 'School timings for students are Monday to Saturday: 7:30 AM to 2:00 PM (Second Saturdays are holidays). Administrative and Admission office timings are Monday to Saturday: 8:30 AM to 4:00 PM.', 'Timings & Schedule', ARRAY['timing', 'timings', 'school hours', 'office hours', 'time', 'opening time', 'closing time', 'working hours'], 2, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Is Decent Public School affiliated with CBSE?', 'Yes, Decent Public School is permanently affiliated with the Central Board of Secondary Education (CBSE), Delhi (Affiliation No. 2730248), offering schooling from Pre-Primary up to Senior Secondary (Class XII).', 'Academics', ARRAY['cbse', 'affiliation', 'board', 'accreditation', 'recognition', 'affiliated'], 3, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Which streams are offered in Classes XI and XII?', 'We offer both Science (Medical and Non-Medical with Physics, Chemistry, Biology, Mathematics, Computer Science/Informatics Practices) and Commerce (Accountancy, Business Studies, Economics, Mathematics, Applied Math) streams with rich elective choices.', 'Academics', ARRAY['streams', 'class 11', 'class 12', 'science stream', 'commerce', 'subjects', 'pcm', 'pcb', 'humanities'], 4, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Does the school provide transport / bus facility?', 'Yes, we have a modern fleet of GPS-tracked, CCTV-enabled air-conditioned buses covering Rohini (all sectors), Pitampura, Shalimar Bagh, Paschim Vihar, Rani Bagh, Mangolpuri, and adjoining North/West Delhi localities. Every bus has a trained female attendant and first aid kit.', 'Transport & Facilities', ARRAY['bus', 'transport', 'routes', 'van', 'pickup', 'commute', 'travel', 'gps'], 5, TRUE),
('a1000000-0000-0000-0000-000000000001', 'What is the fee structure and payment mode?', 'School fees are structured transparently as per Delhi Directorate of Education guidelines and payable quarterly (April, July, October, January). Fees can be paid online via debit/credit card, net banking, UPI on the parent portal, or via demand draft at the fee counter.', 'Fees & Payments', ARRAY['fee', 'fees', 'fee structure', 'payment', 'quarterly', 'cost', 'tuition fee', 'pay fee'], 6, TRUE),
('a1000000-0000-0000-0000-000000000001', 'What is the student-teacher ratio at Decent Public School?', 'We maintain an optimal student-teacher ratio of 25:1 to ensure that every learner receives personalized attention, continuous mentoring, and tailored academic guidance.', 'Academics', ARRAY['ratio', 'student teacher ratio', 'class strength', 'batch size', 'students per class'], 7, TRUE),
('a1000000-0000-0000-0000-000000000001', 'What documents are required at the time of admission?', 'Required documents include: 1) Birth certificate of child, 2) Proof of residential address in Delhi (Voter ID/Aadhaar/Electricity bill), 3) 4 passport-size photographs of child and parents, 4) Previous class report card, 5) Original Transfer Certificate (TC) for Class II and above, 6) Medical fitness certificate.', 'Admissions', ARRAY['documents', 'docs required', 'certificate', 'transfer certificate', 'tc', 'birth certificate', 'requirements'], 8, TRUE),
('a1000000-0000-0000-0000-000000000001', 'Where is Decent Public School located and how to reach?', 'The school is centrally located in Sector 3, Rohini, New Delhi 110085 (near Jaipur Golden Hospital & Madhuban Chowk). It is easily accessible via the Delhi Metro (Rohini West & Rohini East Metro Stations on the Red Line).', 'General', ARRAY['location', 'address', 'where', 'metro', 'reach', 'map', 'directions', 'rohini'], 9, TRUE),
('a1000000-0000-0000-0000-000000000001', 'What sports and co-curricular activities are available?', 'Students engage in Football, Basketball, Badminton, Cricket, Athletics, Table Tennis, Yoga, Taekwondo, Robotic Club, Coding, Debate & Model UN, Western & Classical Music, Theatre, and Eco-Club activities.', 'Transport & Facilities', ARRAY['sports', 'activities', 'games', 'co-curricular', 'extracurricular', 'music', 'dance', 'football', 'clubs'], 10, TRUE);
